create table xxcus.xxfnd_df_flexfields (
    descriptive_flexfield_code   varchar2(60 byte) not null enable,
    application_code             varchar2(30 byte),
    table_name                   varchar2(128 byte) not null enable,
    pk_column_name               varchar2(128 byte) not null enable,
    context_column_name          varchar2(128 byte) default 'ATTRIBUTE_CATEGORY' not null enable,
    context_reference_column     varchar2(128 byte),
    default_context_code         varchar2(80 byte),
    context_required_flag        varchar2(1 byte) default 'N' not null enable,
    context_user_selectable_flag varchar2(1 byte) default 'N' not null enable,
    enabled_flag                 varchar2(1 byte) default 'Y' not null enable,
    created_by                   varchar2(255 byte) not null enable,
    creation_date                timestamp(6) not null enable,
    last_updated_by              varchar2(255 byte) not null enable,
    last_update_date             timestamp(6) not null enable,
    last_update_login            varchar2(255 byte),
    object_version_number        number default 1 not null enable
);

alter table xxcus.xxfnd_df_flexfields
    add constraint xxfnd_df_flexfields_ck1
        check ( context_required_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_df_flexfields
    add constraint xxfnd_df_flexfields_ck2
        check ( context_user_selectable_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_df_flexfields
    add constraint xxfnd_df_flexfields_ck3
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_df_flexfields
    add constraint xxfnd_df_flexfields_pk primary key ( descriptive_flexfield_code )
        using index enable;

alter table xxcus.xxfnd_df_flexfields add constraint xxfnd_df_flexfields_uk1 unique ( table_name )
    using index enable;


